package com.lagcheck.domain

import com.lagcheck.domain.rules.UseCaseEvaluator
import kotlin.test.Test
import kotlin.test.assertEquals

/**
 * Paridade use-cases-v1 com o site. Gabarito gerado executando a função REAL do site
 * (`pages/lagcheck/src/lib/lagcheck/categories.ts` e `media.ts`, monorepo landings) sobre
 * 6285 combinações: cada limite de cada categoria exato e +0,1, cruzando P50 × jitter × Δcarga (com nulos).
 * Formato: p50|jitter|delta|tom geral (O/W/B)|status em ordem fps,br,moba,fighting,casual,voice,streaming,cloud (E/G/C/P). `n` = nulo.
 */
class SiteUseCaseParityTest {
    private val order = listOf("fps", "br", "moba", "fighting", "casual", "voice", "streaming", "cloud")
    private val status = mapOf('E' to UseCaseEvaluator.Status.EXCELLENT, 'G' to UseCaseEvaluator.Status.GOOD, 'C' to UseCaseEvaluator.Status.CAUTION, 'P' to UseCaseEvaluator.Status.POOR)
    private val tone = mapOf('O' to UseCaseEvaluator.OverallTone.OK, 'W' to UseCaseEvaluator.OverallTone.WARN, 'B' to UseCaseEvaluator.OverallTone.BAD)

    @Test
    fun matchesSiteCategoriesOnFullGrid() {
        var checked = 0
        GOLDEN.forEach { chunk ->
            chunk.trim().lines().forEach { line ->
                val p = line.split('|')
                fun num(s: String) = if (s == "n") null else s.toDouble()
                val result = UseCaseEvaluator.evaluate(UseCaseEvaluator.Input(num(p[0]), num(p[1]), num(p[2])))
                assertEquals(tone.getValue(p[3][0]), result.overallTone, "tom geral em $line")
                order.forEachIndexed { i, id ->
                    assertEquals(status.getValue(p[4][i]), result.cases.first { it.id == id }.status, "$id em $line")
                }
                checked++
            }
        }
        assertEquals(6285, checked)
    }

    @Test
    fun matchesSiteUploadTiers() {
        mapOf(0.0 to UseCaseEvaluator.Status.POOR, 2.9 to UseCaseEvaluator.Status.POOR, 3.0 to UseCaseEvaluator.Status.CAUTION, 3.1 to UseCaseEvaluator.Status.CAUTION, 5.9 to UseCaseEvaluator.Status.CAUTION, 6.0 to UseCaseEvaluator.Status.GOOD, 6.1 to UseCaseEvaluator.Status.GOOD, 9.9 to UseCaseEvaluator.Status.GOOD, 10.0 to UseCaseEvaluator.Status.EXCELLENT, 10.1 to UseCaseEvaluator.Status.EXCELLENT, 50.0 to UseCaseEvaluator.Status.EXCELLENT).forEach { (mbps, expected) ->
            assertEquals(expected, UseCaseEvaluator.uploadTier(mbps), "upload $mbps")
        }
    }

    @Test
    fun streamingRowIsWorseOfStabilityAndUploadButOverallIgnoresUpload() {
        val withoutUpload = UseCaseEvaluator.evaluate(UseCaseEvaluator.Input(20.0, 1.0, 5.0))
        val lowUpload = UseCaseEvaluator.evaluate(UseCaseEvaluator.Input(20.0, 1.0, 5.0, uploadMbps = 1.0))
        assertEquals(UseCaseEvaluator.Status.EXCELLENT, withoutUpload.cases.first { it.id == "streaming" }.status)
        assertEquals(UseCaseEvaluator.Status.POOR, lowUpload.cases.first { it.id == "streaming" }.status)
        assertEquals(withoutUpload.overallTone, lowUpload.overallTone)
    }

